<template><div class="app-container"><el-alert title="个人规则优先于平台默认规则；当前 V1 仅对血糖数值执行自动预警。" type="info" :closable="false" style="margin-bottom:16px"/><div class="filter-container"><el-select v-model="query.dataType" clearable placeholder="数据类型"><el-option label="血糖" value="GLUCOSE"/></el-select><el-button type="primary" @click="load">查询</el-button><el-button @click="edit()">新增规则</el-button></div><el-table :data="list" border><el-table-column prop="ruleName" label="规则名称"/><el-table-column prop="ownerUserId" label="用户ID" width="100"/><el-table-column prop="periodCode" label="时段"/><el-table-column prop="minValue" label="下限"/><el-table-column prop="maxValue" label="上限"/><el-table-column prop="alertLevel" label="等级"/><el-table-column prop="enabled" label="启用"/><el-table-column label="操作" width="80"><template slot-scope="{row}"><el-button type="text" @click="edit(row)">编辑</el-button></template></el-table-column></el-table><el-dialog :visible.sync="visible" title="预警规则" width="520px"><el-form label-width="100px"><el-form-item label="规则名称"><el-input v-model="form.ruleName"/></el-form-item><el-form-item label="用户ID"><el-input v-model="form.ownerUserId" placeholder="留空表示平台默认"/></el-form-item><el-form-item label="数据类型"><el-select v-model="form.dataType"><el-option label="血糖" value="GLUCOSE"/></el-select></el-form-item><el-form-item label="检测时段"><el-input v-model="form.periodCode" placeholder="留空适用全部时段"/></el-form-item><el-form-item label="下限"><el-input-number v-model="form.minValue" :precision="2"/></el-form-item><el-form-item label="上限"><el-input-number v-model="form.maxValue" :precision="2"/></el-form-item><el-form-item label="风险等级"><el-select v-model="form.alertLevel"><el-option label="低" value="LOW"/><el-option label="中" value="MEDIUM"/><el-option label="高" value="HIGH"/></el-select></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled"/></el-form-item></el-form><span slot="footer"><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></span></el-dialog></div></template><script>import{getJkHealthAlertRuleList,saveJkHealthAlertRule}from'@/api/jkBusiness';export default{data(){return{query:{page:1,limit:20},list:[],visible:false,form:{dataType:'GLUCOSE',alertLevel:'MEDIUM',enabled:true}}},created(){this.load()},methods:{load(){getJkHealthAlertRuleList(this.query).then(r=>this.list=(r&&r.list)||(r&&r.data&&r.data.list)||r.data||r||[])},edit(row){this.form=row?Object.assign({},row):{dataType:'GLUCOSE',alertLevel:'MEDIUM',enabled:true};this.visible=true},save(){saveJkHealthAlertRule(this.form).then(()=>{this.$message.success('保存成功');this.visible=false;this.load()})}}}</script>